using System.Collections.Generic;

namespace PCCES.CODECHECK;

internal class CodeFitter
{
	private class MrsBaseCls
	{
		public int pubCode;

		public string PccesCode;

		public string cName;

		public string unitName;

		public string Memo;

		public string commonName;
	}

	private List<MrsBaseCls> MrsBases = new List<MrsBaseCls>();

	private Dictionary<string, int> MrsBasesDic = new Dictionary<string, int>();

	private bool isInit = false;

	public int MrsBasesCount => MrsBases.Count;

	private void addMrsBaseRec(int pubCode, string PccesCode, string cName, string unitName, string Memo, string CommonName)
	{
		MrsBaseCls aRec = new MrsBaseCls();
		aRec.pubCode = pubCode;
		aRec.PccesCode = PccesCode;
		MrsBasesDic.Add(PccesCode, pubCode - 1);
		aRec.cName = cName;
		aRec.unitName = unitName;
		aRec.Memo = Memo;
		aRec.commonName = CommonName;
		MrsBases.Add(aRec);
		aRec = null;
	}

	public CodeFitter()
	{
		isInit = false;
		Initialized();
	}

	public MrsBaseData GetMrsBaseData(int iIndex)
	{
		MrsBaseData retV = default(MrsBaseData);
		MrsBaseCls aRec = MrsBases[iIndex];
		retV.pccesCode = aRec.PccesCode;
		retV.cName = aRec.cName;
		retV.unitName = aRec.unitName;
		retV.memo = aRec.Memo;
		retV.commonName = aRec.commonName;
		return retV;
	}

	public bool ValidateCode(string strCode, out string strName, out string strUnit)
	{
		strName = (strUnit = "");
		if (!MrsBasesDic.TryGetValue(strCode, out var PccesIndex))
		{
			return false;
		}
		MrsBaseCls aRec = MrsBases[PccesIndex];
		strName = aRec.cName;
		strUnit = aRec.unitName;
		return true;
	}

